import {products,colors,policies} from "./assets/catalog.js";
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const icon=name=>`<svg aria-hidden="true"><use href="./assets/icons.svg#${name}"></use></svg>`;
const money=value=>new Intl.NumberFormat("en-NG",{style:"currency",currency:"NGN",maximumFractionDigits:0}).format(value);
const basket=[],gift={requested:false,message:""};
let revokePreview=()=>{},returnHash="#shop",opener=null,toastTimer=0;
const detail=$("#detail-dialog"),basketDialog=$("#basket-dialog");
function download(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:"application/json"})),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function toast(message){clearTimeout(toastTimer);$("#toast").textContent=message;$("#toast").hidden=false;toastTimer=setTimeout(()=>$("#toast").hidden=true,3500);}
function filters(){const url=new URL(location.href);return{category:["Slides","Slippers","Sandals"].includes(url.searchParams.get("category"))?url.searchParams.get("category"):"All",query:(url.searchParams.get("q")||"").slice(0,80),sort:["low","high"].includes(url.searchParams.get("sort"))?url.searchParams.get("sort"):"featured"};}
function renderCatalog(){
  const {category,query,sort}=filters();let selected=products.filter(p=>(category==="All"||p.category===category)&&`${p.name} ${p.category} ${p.color}`.toLowerCase().includes(query.toLowerCase().trim()));
  if(sort!=="featured")selected=selected.toSorted((a,b)=>sort==="low"?a.price-b.price:b.price-a.price);
  document.querySelectorAll("[data-filter]").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.filter===category)));
  $("#sort").value=sort;$("#search").value=query;if(query)$("#search-panel").hidden=false;
  $("#results").textContent=`${selected.length} sample ${selected.length===1?"design":"designs"}${query?` matching “${query}”`:""}`;
  $("#product-grid").innerHTML=selected.length?selected.map(p=>`<article class="product-card"><a class="product-art" href="#product-${p.id}" aria-label="Explore ${p.name}"><img src="./assets/${p.id}.svg" width="760" height="520" alt="Original ${p.color.toLowerCase()} ${p.category.toLowerCase()} illustration, ${p.name}" loading="lazy"><span>MADE-ON-DEMAND CONCEPT</span>${icon("plus")}</a><div class="product-title"><h3><a href="#product-${p.id}">${p.name}</a></h3><span class="price">${money(p.price)}</span></div><div class="product-info"><span>${p.category} · sample price</span><span>EU 36–46</span></div><div class="swatches" aria-label="Four sample color choices">${Object.values(colors).map(color=>`<i style="background:${color}"></i>`).join("")}</div></article>`).join(""):`<p class="empty">No designs match. Try another category or clear your search.</p>`;
}
function setFilter(key,value){const url=new URL(location.href);if(value)url.searchParams.set(key,value);else url.searchParams.delete(key);url.hash="shop";history[key==="q"?"replaceState":"pushState"](null,"",url);renderCatalog();}
document.querySelectorAll("[data-filter]").forEach(b=>b.addEventListener("click",()=>setFilter("category",b.dataset.filter==="All"?"":b.dataset.filter)));
$("#sort").addEventListener("change",e=>setFilter("sort",e.target.value==="featured"?"":e.target.value));
$("#search").addEventListener("input",e=>setFilter("q",e.target.value));
$("#clear-search").addEventListener("click",()=>{setFilter("q","");$("#search").focus();});
$("#search-button").addEventListener("click",()=>{$("#search-panel").hidden=false;$("#shop").scrollIntoView();$("#search").focus({preventScroll:true});});
function updateCount(){const count=basket.reduce((n,line)=>n+line.quantity,0);$("#cart-count").textContent=count;$("#drawer-count").textContent=count;$("#cart-button").setAttribute("aria-label",`Open draft basket, ${count} items`);}
function invalidateDraft(){$("#draft-ack").checked=false;$("#download-draft").disabled=true;$("#basket-status").textContent="";}
function renderBasket(){
  updateCount();invalidateDraft();
  $("#basket-items").innerHTML=basket.length?basket.map((line,i)=>{const p=products.find(p=>p.id===line.id);return`<article class="basket-item"><img src="./assets/${p.id}-${line.color.toLowerCase()}.svg" width="760" height="520" alt="${line.color} ${p.name} illustration"><div><h3>${p.name}</h3><p>EU ${line.size} / ${line.color}</p>${line.notes?`<p class="pending">Edit request · approval pending</p><p>${esc(line.notes)}</p>`:"<p>Standard sample design</p>"}<div class="quantity"><button data-action="minus" data-line="${i}" aria-label="Decrease ${p.name} quantity">−</button><span>${line.quantity}</span><button data-action="plus" data-line="${i}" ${line.quantity===5?"disabled":""} aria-label="Increase ${p.name} quantity">+</button><button class="remove" data-action="remove" data-line="${i}">Remove</button></div><span class="basket-item-price">${money(p.price*line.quantity)} · sample base only</span></div></article>`;}).join(""):`<div class="empty"><p>Your next pair starts here.</p><button class="button black" id="browse-designs">Explore sample designs ${icon("arrow-right")}</button></div>`;
  $("#subtotal").textContent=money(basket.reduce((n,line)=>n+products.find(p=>p.id===line.id).price*line.quantity,0));
  $("#basket-extra").innerHTML=basket.length?`<div class="gift-section"><label><input id="gift-request" type="checkbox" ${gift.requested?"checked":""}>Request gift packaging & a greeting card</label><div id="gift-fields" ${gift.requested?"":"hidden"}><label class="sr-label">Greeting message (optional, 160 characters)<textarea id="gift-message" maxlength="160" placeholder="A little note for someone special">${esc(gift.message)}</textarea></label><p>Packaging, availability and any extra charge need approval. No gift is sent.</p></div></div>`:"";
  if(basket.length){$("#gift-request").addEventListener("change",e=>{gift.requested=e.target.checked;$("#gift-fields").hidden=!gift.requested;invalidateDraft();});$("#gift-message").addEventListener("input",e=>{gift.message=e.target.value;invalidateDraft();});}
  $("#draft-ack").disabled=!basket.length;
  $("#browse-designs")?.addEventListener("click",()=>{basketDialog.close();location.hash="shop";$("#shop").scrollIntoView();});
}
$("#basket-items").addEventListener("click",e=>{const b=e.target.closest("[data-action]");if(!b)return;const i=Number(b.dataset.line),line=basket[i];if(!line)return;if(b.dataset.action==="remove")basket.splice(i,1);else{line.quantity+=b.dataset.action==="plus"?1:-1;if(line.quantity<=0)basket.splice(i,1);}renderBasket();const next=document.querySelector(`[data-line="${i}"][data-action="${b.dataset.action}"]:not(:disabled)`);(next||$("#close-basket")).focus({preventScroll:true});});
$("#cart-button").addEventListener("click",()=>{renderBasket();basketDialog.showModal();});$("#close-basket").addEventListener("click",()=>basketDialog.close());
$("#draft-ack").addEventListener("change",e=>$("#download-draft").disabled=!basket.length||!e.target.checked);
$("#download-draft").addEventListener("click",()=>{if(!basket.length||!$("#draft-ack").checked)return;const subtotal=basket.reduce((n,line)=>n+products.find(p=>p.id===line.id).price*line.quantity,0);download({kind:"D’FOOTPRINT sample order draft",status:"Not submitted. Not an order. Not paid.",currency:"NGN",items:basket.map(line=>({...line,name:products.find(p=>p.id===line.id).name,baseUnitPrice:products.find(p=>p.id===line.id).price,customApproval:line.notes?"pending":"not requested"})),gift:{requested:gift.requested,message:gift.requested?gift.message:"",approval:gift.requested?"pending":"not requested",fee:null},sampleDesignSubtotal:subtotal,deliveryFee:null,customFees:null,finalTotal:null},"dfootprint-draft.json");$("#basket-status").textContent="Draft downloaded. Nothing was sent, ordered or paid.";});
function openProduct(p){
  $("#detail-content").innerHTML=`<div class="detail-grid"><div class="detail-image"><img id="variant-image" src="./assets/${p.id}-${p.color.toLowerCase()}.svg" width="760" height="520" alt="${p.color} ${p.name} original illustration"><p>ORIGINAL ILLUSTRATION / NOT PRODUCT PHOTOGRAPHY</p></div><div class="detail-copy"><p class="eyebrow">${p.category.toUpperCase()} / MADE-ON-DEMAND CONCEPT</p><h2 id="detail-title">${p.name}</h2><p class="detail-price">${money(p.price)} <small>sample base price</small></p><p>${p.material}</p><p>Fit, materials, availability and production timing require seller confirmation. Delivery is paid separately; no delivery fee has been quoted.</p><form class="detail-form" id="product-form" novalidate><label>EU size (sample range)<select id="size" required aria-describedby="product-error"><option value="">Choose your size</option>${Array.from({length:11},(_,i)=>`<option value="${i+36}">${i+36}</option>`).join("")}</select></label><fieldset><legend>Color · illustration updates with selection</legend><div class="color-options">${Object.entries(colors).map(([name,color])=>`<label><input type="radio" name="color" value="${name}" ${name===p.color?"checked":""}><i style="background:${color}"></i>${name}</label>`).join("")}</div></fieldset><label>Request an edit (optional)<textarea id="edit-notes" maxlength="400" placeholder="Describe an edit. Approval and any added fee are separate."></textarea></label><p class="small-note">Every edit is subject to review. A note does not approve or price a change. Returns are reviewed case by case; final terms need seller confirmation.</p><p id="product-error" class="error" role="status"></p><button class="button black">Add to draft basket ${icon("plus")}</button></form></div></div>`;
  $("#product-form").addEventListener("change",e=>{if(e.target.name!=="color")return;const color=e.target.value;$("#variant-image").src=`./assets/${p.id}-${color.toLowerCase()}.svg`;$("#variant-image").alt=`${color} ${p.name} original illustration`;});
  $("#product-form").addEventListener("submit",e=>{e.preventDefault();const size=Number($("#size").value),color=$('#product-form input[name="color"]:checked')?.value,notes=$("#edit-notes").value.trim();if(size<36||size>46||!Object.hasOwn(colors,color)){$("#product-error").textContent="Choose a size from EU 36–46.";$("#size").focus();return;}const existing=basket.find(line=>line.id===p.id&&line.size===size&&line.color===color&&line.notes===notes);if(existing?.quantity===5||(!existing&&basket.length>=12)){$("#product-error").textContent="Draft limit: five of one variant and twelve separate lines.";return;}if(existing)existing.quantity++;else basket.push({id:p.id,size,color,notes,quantity:1});updateCount();closeDetail();toast(notes?"Added as a draft. Your edit still needs approval.":"Added to your local draft basket.");});
}
function openCustom(){
  $("#detail-content").innerHTML=`<div class="custom-form-wrap"><p class="eyebrow">CUSTOM IS A CONVERSATION</p><h2 id="detail-title">Your idea, in a little detail.</h2><p>Describe a new design or an edit. The maker must review feasibility, materials, extra costs and timing before approval. This local tool cannot send, price or approve your request.</p><form id="custom-form" novalidate><label>Design reference (optional JPG, PNG or WebP, up to 5 MB)<input type="file" id="reference" accept="image/jpeg,image/png,image/webp" aria-describedby="reference-status"></label><p class="small-note" id="reference-status" role="status">Image preview stays in your browser. The JSON includes its filename only; attach the image separately when a verified contact is available.</p><img id="reference-preview" class="upload-preview" alt="Your local design reference preview" hidden><label>Requested EU size<select id="custom-size"><option value="">Choose a size</option>${Array.from({length:11},(_,i)=>`<option value="${36+i}">${36+i}</option>`).join("")}</select></label><label>Your idea (20–1000 characters)<textarea id="custom-notes" minlength="20" maxlength="1000" placeholder="Tell us what you like, what you would change, and any material or color preferences."></textarea></label><p id="custom-error" class="error" role="status"></p><button class="button black">Download request for review ${icon("download")}</button><p id="custom-status" class="form-success" role="status">No upload, approval or message is sent.</p></form></div>`;
  let reference=null,fileValid=true,serial=0,active=true,previewUrl="";
  const clearPreview=()=>{if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl="";};
  revokePreview=()=>{active=false;serial++;clearPreview();};
  $("#reference").addEventListener("change",async e=>{
    const request=++serial,file=e.target.files[0];reference=null;fileValid=true;clearPreview();$("#reference-preview").hidden=true;
    if(!file){$("#reference-status").textContent="No reference selected. Nothing uploaded.";return;}
    if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>5*1024*1024){fileValid=false;$("#reference-status").textContent="Choose JPG, PNG or WebP up to 5 MB. No reference accepted.";return;}
    fileValid=false;$("#reference-status").textContent="Checking the local image…";
    let header;try{header=new Uint8Array(await file.slice(0,12).arrayBuffer());}catch{if(active&&request===serial)$("#reference-status").textContent="The local file could not be read. Select it again.";return;}
    const signature=Array.from(header.slice(0,8)).map(n=>n.toString(16).padStart(2,"0")).join("");
    const recognized=file.type==="image/png"?signature==="89504e470d0a1a0a":file.type==="image/jpeg"?header[0]===255&&header[1]===216&&header[2]===255:new TextDecoder().decode(header.slice(0,4))==="RIFF"&&new TextDecoder().decode(header.slice(8,12))==="WEBP";
    if(!active||request!==serial)return;
    if(!recognized){$("#reference-status").textContent="File content does not match an accepted image format. No reference accepted.";return;}
    const url=URL.createObjectURL(file),img=new Image();img.src=url;
    try{await img.decode();if(!active||request!==serial){URL.revokeObjectURL(url);return;}reference={name:file.name,size:file.size,type:file.type,imageIncluded:false};fileValid=true;previewUrl=url;$("#reference-preview").src=url;$("#reference-preview").hidden=false;$("#reference-status").textContent=`${file.name} · local preview only. Export contains the filename, not the image.`;}catch{URL.revokeObjectURL(url);if(active&&request===serial)$("#reference-status").textContent="This file could not be decoded as an image. No reference accepted.";}
  });
  $("#custom-form").addEventListener("submit",e=>{e.preventDefault();const size=Number($("#custom-size").value),notes=$("#custom-notes").value.trim();if(size<36||size>46||notes.length<20||notes.length>1000||!fileValid){$("#custom-error").textContent="Choose a size, describe the idea in 20–1000 characters, and use a valid reference if selected.";return;}download({kind:"D’FOOTPRINT custom review request",status:"Not submitted. Approval pending.",size,notes,reference,quotedPrice:null,deliveryFee:null,productionTiming:null},"dfootprint-custom-request.json");$("#custom-error").textContent="";$("#custom-status").textContent="Request downloaded. Nothing was sent or approved. Reference image is not included in the JSON.";});
}
function restore(){
  if(basketDialog.open)basketDialog.close();
  revokePreview();revokePreview=()=>{};
  const hash=location.hash.slice(1),p=products.find(p=>hash===`product-${p.id}`),policy=policies[hash.replace(/^policy-/,"")];
  if(p||hash==="custom-request"||hash.startsWith("policy-")&&policy){
    if(!detail.open){opener=document.activeElement;detail.showModal();}
    if(p)openProduct(p);else if(hash==="custom-request")openCustom();else $("#detail-content").innerHTML=`<article class="policy-copy"><p class="eyebrow">SAMPLE INFORMATION / REVIEW BEFORE LIVE USE</p><h2 id="detail-title">${policy.title}</h2>${policy.body.map(([heading,body])=>`<h3>${heading}</h3><p>${body}</p>`).join("")}</article>`;
    detail.scrollTop=0;$(".close-detail").focus({preventScroll:true});
  }else if(detail.open){detail.close();$("#detail-content").replaceChildren();}
  renderCatalog();
}
function closeDetail(){const origin=location.hash;history.pushState(null,"",returnHash);restore();const target=opener?.isConnected?opener:document.querySelector(`a[href="${origin}"]`);target?.focus({preventScroll:true});}
$(".close-detail").addEventListener("click",closeDetail);detail.addEventListener("cancel",e=>{e.preventDefault();closeDetail();});
document.addEventListener("click",e=>{const a=e.target.closest('a[href^="#product-"],a[href^="#policy-"]');if(a)returnHash=location.hash&&!/^#(?:product|policy)-/.test(location.hash)?location.hash:"#shop";});
$("#custom-button").addEventListener("click",()=>{returnHash="#custom";location.hash="custom-request";});
window.addEventListener("hashchange",restore);window.addEventListener("popstate",restore);
$(".mobile-toggle").addEventListener("click",()=>{const open=!$("#navigation").classList.contains("open");$("#navigation").classList.toggle("open",open);$(".mobile-toggle").setAttribute("aria-expanded",String(open));$(".mobile-toggle").setAttribute("aria-label",open?"Close navigation":"Open navigation");});
$("#navigation").addEventListener("click",e=>{if(e.target.closest("a")){$("#navigation").classList.remove("open");$(".mobile-toggle").setAttribute("aria-expanded","false");$(".mobile-toggle").setAttribute("aria-label","Open navigation");}});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&$("#navigation").classList.contains("open")){$(".mobile-toggle").click();$(".mobile-toggle").focus();}});
renderBasket();restore();
